KIND = "questions"
SYSTEM = "muscular"
E = {
"mu-b889ed68": {
"en": ["Which is the only laryngeal muscle that opens the rima glottidis (abducts the vocal folds)?",
 ["Cricothyroid", "Thyroarytenoid", "Posterior cricoarytenoid", "Lateral cricoarytenoid", "Arytenoid"],
 "Posterior cricoarytenoid pulls the muscular processes of the arytenoids backwards, rotating the vocal processes outwards and opening the glottis. In bilateral recurrent laryngeal nerve injury paralysis of these muscles leaves the vocal folds in the midline, with stridor and respiratory distress.",
 ["It tenses the vocal folds; it does not open them.", "It relaxes the vocal folds.", "", "It brings the vocal folds together.", "It draws the arytenoids together and closes the posterior glottis."]],
"fr": ["Quel est le seul muscle laryngé qui ouvre la fente glottique (écarte les plis vocaux) ?",
 ["Crico-thyroïdien", "Thyro-aryténoïdien", "Crico-aryténoïdien postérieur", "Crico-aryténoïdien latéral", "Aryténoïdien"],
 "Le crico-aryténoïdien postérieur tire en arrière les processus musculaires des aryténoïdes, fait tourner les processus vocaux en dehors et ouvre la glotte. Dans la lésion récurrentielle bilatérale, leur paralysie laisse les plis vocaux en position médiane, avec stridor et détresse respiratoire.",
 ["Il tend les plis vocaux ; il ne les ouvre pas.", "Il relâche les plis vocaux.", "", "Il rapproche les plis vocaux.", "Il rapproche les aryténoïdes et ferme la partie postérieure de la glotte."]],
"de": ["Welches ist der einzige Kehlkopfmuskel, der die Stimmritze öffnet (die Stimmlippen abduziert)?",
 ["M. cricothyroideus", "M. thyroarytenoideus", "M. cricoarytenoideus posterior", "M. cricoarytenoideus lateralis", "M. arytenoideus"],
 "Der Cricoarytenoideus posterior („Posticus“) zieht die Processus musculares der Aryknorpel nach hinten, dreht die Processus vocales nach außen und öffnet die Glottis. Bei beidseitiger Rekurrensläsion bleiben die Stimmlippen durch ihre Lähmung in Medianstellung; es kommt zu Stridor und Atemnot.",
 ["Er spannt die Stimmlippen, öffnet sie aber nicht.", "Er entspannt die Stimmlippen.", "", "Er nähert die Stimmlippen an.", "Er nähert die Aryknorpel an und schließt den hinteren Glottisteil."]],
"es": ["¿Cuál es el único músculo laríngeo que abre la hendidura glótica (abduce los pliegues vocales)?",
 ["Cricotiroideo", "Tiroaritenoideo", "Cricoaritenoideo posterior", "Cricoaritenoideo lateral", "Aritenoideo"],
 "El cricoaritenoideo posterior tira hacia atrás de las apófisis musculares de los aritenoides, gira hacia fuera las apófisis vocales y abre la glotis. En la lesión recurrencial bilateral su parálisis deja los pliegues vocales en la línea media, con estridor y dificultad respiratoria.",
 ["Tensa los pliegues vocales; no los abre.", "Relaja los pliegues vocales.", "", "Aproxima los pliegues vocales.", "Acerca los aritenoides y cierra la parte posterior de la glotis."]],
},
"mu-19279b2e": {
"en": ["After total thyroidectomy a patient becomes hoarse. Laryngoscopy shows the left vocal fold immobile in the paramedian position. Which nerve has been damaged?",
 ["Internal branch of the left superior laryngeal nerve", "Left recurrent laryngeal nerve", "Superior root of the ansa cervicalis", "Left hypoglossal nerve", "External branch of the left superior laryngeal nerve"],
 "The recurrent laryngeal nerve supplies all intrinsic laryngeal muscles except cricothyroid and lies close to the inferior thyroid artery. In unilateral injury the vocal fold stays in the paramedian position and the voice is hoarse. Injury to the external branch causes voice fatigue and difficulty with high notes; the internal branch is sensory.",
 ["It carries sensation from the mucosa above the glottis; it is not motor.", "", "It supplies the infrahyoid muscles.", "It supplies the tongue muscles.", "It supplies only cricothyroid."]],
"fr": ["Après une thyroïdectomie totale, un patient devient dysphonique. La laryngoscopie montre le pli vocal gauche immobile en position paramédiane. Quel nerf a été lésé ?",
 ["Rameau interne du nerf laryngé supérieur gauche", "Nerf laryngé récurrent gauche", "Racine supérieure de l'anse cervicale", "Nerf hypoglosse gauche", "Rameau externe du nerf laryngé supérieur gauche"],
 "Le nerf laryngé récurrent innerve tous les muscles intrinsèques du larynx sauf le crico-thyroïdien et est en rapport étroit avec l'artère thyroïdienne inférieure. Dans une lésion unilatérale, le pli vocal reste en position paramédiane et la voix est rauque. La lésion du rameau externe donne une fatigabilité vocale et une difficulté pour les aigus ; le rameau interne est sensitif.",
 ["Il assure la sensibilité de la muqueuse sus-glottique ; il n'est pas moteur.", "", "Elle innerve les muscles infrahyoïdiens.", "Il innerve les muscles de la langue.", "Il n'innerve que le crico-thyroïdien."]],
"de": ["Nach totaler Thyreoidektomie wird ein Patient heiser. Laryngoskopisch steht die linke Stimmlippe unbeweglich in Paramedianstellung. Welcher Nerv wurde geschädigt?",
 ["R. internus des linken N. laryngeus superior", "Linker N. laryngeus recurrens", "Obere Wurzel der Ansa cervicalis", "Linker N. hypoglossus", "R. externus des linken N. laryngeus superior"],
 "Der N. laryngeus recurrens innerviert alle inneren Kehlkopfmuskeln außer dem Cricothyroideus und liegt eng an der A. thyroidea inferior. Bei einseitiger Läsion bleibt die Stimmlippe paramedian stehen, die Stimme ist heiser. Eine Läsion des R. externus verursacht Stimmermüdung und Probleme mit hohen Tönen; der R. internus ist sensibel.",
 ["Er leitet die Sensibilität der supraglottischen Schleimhaut; er ist nicht motorisch.", "", "Sie innerviert die infrahyoidalen Muskeln.", "Er innerviert die Zungenmuskeln.", "Er innerviert nur den Cricothyroideus."]],
"es": ["Tras una tiroidectomía total un paciente presenta ronquera. La laringoscopia muestra el pliegue vocal izquierdo inmóvil en posición paramedia. ¿Qué nervio se ha dañado?",
 ["Rama interna del laríngeo superior izquierdo", "Laríngeo recurrente izquierdo", "Raíz superior del asa cervical", "Hipogloso izquierdo", "Rama externa del laríngeo superior izquierdo"],
 "El laríngeo recurrente inerva todos los músculos intrínsecos de la laringe salvo el cricotiroideo y está muy próximo a la arteria tiroidea inferior. En la lesión unilateral el pliegue vocal queda en posición paramedia y la voz se vuelve ronca. La lesión de la rama externa produce fatiga vocal y dificultad para los agudos; la rama interna es sensitiva.",
 ["Recoge la sensibilidad de la mucosa supraglótica; no es motora.", "", "Inerva los músculos infrahioideos.", "Inerva los músculos de la lengua.", "Solo inerva el cricotiroideo."]],
},
"mu-0d2b8196": {
"en": ["Which is the only pharyngeal muscle supplied by the glossopharyngeal nerve?",
 ["Stylopharyngeus", "Superior pharyngeal constrictor", "Palatopharyngeus", "Salpingopharyngeus", "Inferior pharyngeal constrictor"],
 "All the pharyngeal muscles are supplied by the vagus through the pharyngeal plexus; the only exception is stylopharyngeus, arising from the styloid process (glossopharyngeal nerve). It enters the pharynx between the superior and middle constrictors and raises the pharynx in swallowing.", []],
"fr": ["Quel est le seul muscle du pharynx innervé par le nerf glosso-pharyngien ?",
 ["Stylo-pharyngien", "Constricteur supérieur du pharynx", "Palato-pharyngien", "Salpingo-pharyngien", "Constricteur inférieur du pharynx"],
 "Tous les muscles du pharynx sont innervés par le nerf vague via le plexus pharyngien ; seule exception, le stylo-pharyngien, né du processus styloïde (nerf glosso-pharyngien). Il pénètre dans le pharynx entre les constricteurs supérieur et moyen et élève le pharynx lors de la déglutition.", []],
"de": ["Welches ist der einzige Rachenmuskel, der vom N. glossopharyngeus innerviert wird?",
 ["M. stylopharyngeus", "M. constrictor pharyngis superior", "M. palatopharyngeus", "M. salpingopharyngeus", "M. constrictor pharyngis inferior"],
 "Alle Rachenmuskeln werden über den Plexus pharyngeus vom N. vagus innerviert; einzige Ausnahme ist der vom Processus styloideus entspringende M. stylopharyngeus (N. glossopharyngeus). Er tritt zwischen oberem und mittlerem Schlundschnürer in den Rachen ein und hebt ihn beim Schlucken.", []],
"es": ["¿Cuál es el único músculo faríngeo inervado por el glosofaríngeo?",
 ["Estilofaríngeo", "Constrictor superior de la faringe", "Palatofaríngeo", "Salpingofaríngeo", "Constrictor inferior de la faringe"],
 "Todos los músculos faríngeos los inerva el vago a través del plexo faríngeo; la única excepción es el estilofaríngeo, que nace de la apófisis estiloides (glosofaríngeo). Entra en la faringe entre los constrictores superior y medio y la eleva al tragar.", []],
},
"mu-d0f50799": {
"en": ["Where is Killian's triangle, through which a Zenker diverticulum emerges?",
 ["Between the middle and inferior constrictors", "Between the cricopharyngeal fibres and the longitudinal muscle layer of the oesophagus", "Between the thyropharyngeal and cricopharyngeal fibres of the inferior pharyngeal constrictor", "Between the superior and middle constrictors", "Between stylopharyngeus and the superior constrictor"],
 "Killian's triangle is the weak posterior area between the oblique thyropharyngeal fibres and the horizontal cricopharyngeal fibres (upper oesophageal sphincter) of the inferior constrictor. When the cricopharyngeal fibres fail to relax, the mucosa herniates backwards here. The area between cricopharyngeus and the oesophageal muscles is Laimer's triangle.", []],
"fr": ["Où se situe le triangle de Killian, par lequel sort le diverticule de Zenker ?",
 ["Entre les constricteurs moyen et inférieur", "Entre les fibres crico-pharyngiennes et la couche longitudinale de l'œsophage", "Entre les fibres thyro-pharyngiennes et crico-pharyngiennes du constricteur inférieur du pharynx", "Entre les constricteurs supérieur et moyen", "Entre le stylo-pharyngien et le constricteur supérieur"],
 "Le triangle de Killian est la zone faible postérieure comprise entre les fibres obliques thyro-pharyngiennes et les fibres horizontales crico-pharyngiennes (sphincter supérieur de l'œsophage) du constricteur inférieur. Quand les fibres crico-pharyngiennes ne se relâchent pas, la muqueuse hernie en arrière à ce niveau. La zone entre crico-pharyngien et muscles œsophagiens est le triangle de Laimer.", []],
"de": ["Wo liegt das Killian-Dreieck, durch das ein Zenker-Divertikel austritt?",
 ["Zwischen mittlerem und unterem Schlundschnürer", "Zwischen den krikopharyngealen Fasern und der Längsmuskulatur des Ösophagus", "Zwischen den thyropharyngealen und krikopharyngealen Fasern des M. constrictor pharyngis inferior", "Zwischen oberem und mittlerem Schlundschnürer", "Zwischen M. stylopharyngeus und oberem Schlundschnürer"],
 "Das Killian-Dreieck ist die hintere Schwachstelle zwischen den schrägen Fasern der Pars thyropharyngea und den queren Fasern der Pars cricopharyngea (oberer Ösophagussphinkter) des unteren Schlundschnürers. Erschlafft die Pars cricopharyngea nicht, stülpt sich hier die Schleimhaut nach hinten aus. Der Bereich zwischen Cricopharyngeus und Ösophagusmuskulatur ist das Laimer-Dreieck.", []],
"es": ["¿Dónde se encuentra el triángulo de Killian, por donde sale el divertículo de Zenker?",
 ["Entre los constrictores medio e inferior", "Entre las fibras cricofaríngeas y la capa longitudinal del esófago", "Entre las fibras tirofaríngeas y cricofaríngeas del constrictor inferior de la faringe", "Entre los constrictores superior y medio", "Entre el estilofaríngeo y el constrictor superior"],
 "El triángulo de Killian es la zona débil posterior entre las fibras oblicuas tirofaríngeas y las horizontales cricofaríngeas (esfínter esofágico superior) del constrictor inferior. Cuando las fibras cricofaríngeas no se relajan, la mucosa se hernia hacia atrás por aquí. La zona entre el cricofaríngeo y los músculos esofágicos es el triángulo de Laimer.", []],
},
"mu-4997b610": {
"en": ["Which muscle, lying deep to trapezius at the back of the neck, turns the head to the same side?",
 ["Upper fibres of trapezius", "Splenius capitis", "Scalenus anterior", "Levator scapulae", "Sternocleidomastoid"],
 "Splenius capitis arises from the nuchal ligament and upper thoracic spinous processes and attaches to the mastoid process and superior nuchal line; contracting on one side it turns the head to the same side. SCM turns the face to the opposite side; the two muscles work together in turning the head.",
 ["It tilts the head to the same side and turns the face to the opposite side.", "", "It bends the neck to the same side; it does not turn the head.", "It elevates the scapula.", "It turns the face to the opposite side."]],
"fr": ["Quel muscle, situé sous le trapèze à la nuque, tourne la tête du même côté ?",
 ["Fibres supérieures du trapèze", "Splénius de la tête", "Scalène antérieur", "Élévateur de la scapula", "Sterno-cléido-mastoïdien"],
 "Le splénius de la tête naît du ligament nucal et des processus épineux thoraciques hauts et s'insère sur le processus mastoïde et la ligne nucale supérieure ; en contraction unilatérale, il tourne la tête du même côté. Le SCM tourne la face du côté opposé ; les deux muscles agissent ensemble dans la rotation de la tête.",
 ["Elles inclinent la tête du même côté et tournent la face du côté opposé.", "", "Il incline le cou du même côté ; il ne tourne pas la tête.", "Il élève la scapula.", "Il tourne la face du côté opposé."]],
"de": ["Welcher Muskel unter dem Trapezius im Nacken dreht den Kopf zur gleichen Seite?",
 ["Obere Fasern des M. trapezius", "M. splenius capitis", "M. scalenus anterior", "M. levator scapulae", "M. sternocleidomastoideus"],
 "Der Splenius capitis entspringt am Lig. nuchae und an den oberen Brustwirbeldornfortsätzen und setzt am Processus mastoideus und an der Linea nuchae superior an; einseitig dreht er den Kopf zur gleichen Seite. Der SCM dreht das Gesicht zur Gegenseite; beide Muskeln arbeiten bei der Kopfdrehung zusammen.",
 ["Sie neigen den Kopf zur gleichen Seite und drehen das Gesicht zur Gegenseite.", "", "Er neigt den Hals zur gleichen Seite, dreht den Kopf aber nicht.", "Er hebt das Schulterblatt.", "Er dreht das Gesicht zur Gegenseite."]],
"es": ["¿Qué músculo, situado profundo al trapecio en la nuca, gira la cabeza hacia el mismo lado?",
 ["Fibras superiores del trapecio", "Esplenio de la cabeza", "Escaleno anterior", "Elevador de la escápula", "Esternocleidomastoideo"],
 "El esplenio de la cabeza nace del ligamento nucal y de las apófisis espinosas torácicas altas y se inserta en la apófisis mastoides y la línea nucal superior; en contracción unilateral gira la cabeza hacia el mismo lado. El ECM gira la cara al lado opuesto; ambos músculos actúan juntos en la rotación de la cabeza.",
 ["Inclinan la cabeza al mismo lado y giran la cara al opuesto.", "", "Inclina el cuello al mismo lado; no gira la cabeza.", "Eleva la escápula.", "Gira la cara al lado opuesto."]],
},
"mu-48308dfb": {
"en": ["Which muscles bound the suboccipital triangle?",
 ["Longissimus capitis, rectus capitis posterior major and obliquus capitis inferior", "Rectus capitis posterior minor, obliquus capitis superior and inferior", "Rectus capitis posterior minor and major, and obliquus capitis inferior", "Semispinalis capitis, splenius capitis and obliquus capitis superior", "Rectus capitis posterior major, obliquus capitis superior and obliquus capitis inferior"],
 "The superomedial border of the triangle is rectus capitis posterior major, the superolateral border obliquus capitis superior and the inferior border obliquus capitis inferior. Its floor is the posterior arch of the atlas and posterior atlanto-occipital membrane; it contains the vertebral artery and suboccipital nerve; its roof is covered by semispinalis capitis.", []],
"fr": ["Quels muscles limitent le triangle sous-occipital ?",
 ["Longissimus de la tête, grand droit postérieur de la tête et oblique inférieur de la tête", "Petit droit postérieur de la tête, obliques supérieur et inférieur de la tête", "Petit et grand droits postérieurs de la tête et oblique inférieur de la tête", "Semi-épineux de la tête, splénius de la tête et oblique supérieur de la tête", "Grand droit postérieur de la tête, oblique supérieur et oblique inférieur de la tête"],
 "Le bord supéro-médial du triangle est formé par le grand droit postérieur de la tête, le bord supéro-latéral par l'oblique supérieur et le bord inférieur par l'oblique inférieur. Son fond est l'arc postérieur de l'atlas et la membrane atlanto-occipitale postérieure ; il contient l'artère vertébrale et le nerf sous-occipital ; son toit est recouvert par le semi-épineux de la tête.", []],
"de": ["Welche Muskeln begrenzen das Trigonum suboccipitale?",
 ["M. longissimus capitis, M. rectus capitis posterior major und M. obliquus capitis inferior", "M. rectus capitis posterior minor, M. obliquus capitis superior und inferior", "M. rectus capitis posterior minor und major sowie M. obliquus capitis inferior", "M. semispinalis capitis, M. splenius capitis und M. obliquus capitis superior", "M. rectus capitis posterior major, M. obliquus capitis superior und M. obliquus capitis inferior"],
 "Die obere mediale Grenze des Dreiecks bildet der Rectus capitis posterior major, die obere laterale der Obliquus capitis superior und die untere der Obliquus capitis inferior. Den Boden bilden hinterer Atlasbogen und Membrana atlantooccipitalis posterior; darin liegen A. vertebralis und N. suboccipitalis; das Dach bedeckt der Semispinalis capitis.", []],
"es": ["¿Qué músculos limitan el triángulo suboccipital?",
 ["Longísimo de la cabeza, recto posterior mayor de la cabeza y oblicuo inferior de la cabeza", "Recto posterior menor de la cabeza, oblicuos superior e inferior de la cabeza", "Rectos posteriores menor y mayor de la cabeza y oblicuo inferior", "Semiespinoso de la cabeza, esplenio de la cabeza y oblicuo superior", "Recto posterior mayor de la cabeza, oblicuo superior y oblicuo inferior de la cabeza"],
 "El borde superomedial del triángulo lo forma el recto posterior mayor, el superolateral el oblicuo superior y el inferior el oblicuo inferior. Su suelo es el arco posterior del atlas y la membrana atlantooccipital posterior; contiene la arteria vertebral y el nervio suboccipital, y su techo lo cubre el semiespinoso de la cabeza.", []],
},
"mu-6c14a49e": {
"en": ["Which nerve supplies the suboccipital muscles?",
 ["Lesser occipital nerve (anterior ramus of C2)", "Greater occipital nerve (posterior ramus of C2)", "Accessory nerve", "Third occipital nerve (posterior ramus of C3)", "Suboccipital nerve (posterior ramus of C1)"],
 "The suboccipital nerve, the posterior ramus of C1, emerges between the vertebral artery and the posterior arch of the atlas and supplies all the muscles of the suboccipital triangle; it usually has no cutaneous branch. The greater occipital nerve emerges below obliquus capitis inferior and supplies the skin of the back of the neck and scalp.",
 ["It carries sensation from the skin behind the ear.", "It carries sensation from the back of the neck and scalp; it does not supply the suboccipital muscles.", "It supplies trapezius and SCM.", "It supplies the skin of the lower back of the neck.", ""]],
"fr": ["Quel nerf innerve les muscles sous-occipitaux ?",
 ["Petit nerf occipital (rameau antérieur de C2)", "Grand nerf occipital (rameau postérieur de C2)", "Nerf accessoire", "Troisième nerf occipital (rameau postérieur de C3)", "Nerf sous-occipital (rameau postérieur de C1)"],
 "Le nerf sous-occipital, rameau postérieur de C1, émerge entre l'artère vertébrale et l'arc postérieur de l'atlas et innerve tous les muscles du triangle sous-occipital ; il n'a généralement pas de branche cutanée. Le grand nerf occipital émerge sous l'oblique inférieur de la tête et innerve la peau de la nuque et du cuir chevelu.",
 ["Il assure la sensibilité de la peau rétro-auriculaire.", "Il assure la sensibilité de la nuque et du cuir chevelu ; il n'innerve pas les sous-occipitaux.", "Il innerve le trapèze et le SCM.", "Il innerve la peau de la partie basse de la nuque.", ""]],
"de": ["Welcher Nerv innerviert die subokzipitalen Muskeln?",
 ["N. occipitalis minor (R. anterior C2)", "N. occipitalis major (R. posterior C2)", "N. accessorius", "N. occipitalis tertius (R. posterior C3)", "N. suboccipitalis (R. posterior C1)"],
 "Der N. suboccipitalis, der R. posterior von C1, tritt zwischen A. vertebralis und hinterem Atlasbogen aus und versorgt alle Muskeln des Trigonum suboccipitale; meist hat er keinen Hautast. Der N. occipitalis major tritt unter dem Obliquus capitis inferior hervor und versorgt die Haut von Nacken und Hinterkopf.",
 ["Er versorgt sensibel die Haut hinter dem Ohr.", "Er versorgt sensibel Nacken und Kopfhaut, nicht die subokzipitalen Muskeln.", "Er innerviert Trapezius und SCM.", "Er versorgt die Haut des unteren Nackens.", ""]],
"es": ["¿Qué nervio inerva los músculos suboccipitales?",
 ["Nervio occipital menor (ramo anterior de C2)", "Nervio occipital mayor (ramo posterior de C2)", "Nervio accesorio", "Tercer nervio occipital (ramo posterior de C3)", "Nervio suboccipital (ramo posterior de C1)"],
 "El nervio suboccipital, ramo posterior de C1, sale entre la arteria vertebral y el arco posterior del atlas e inerva todos los músculos del triángulo suboccipital; suele carecer de rama cutánea. El occipital mayor sale por debajo del oblicuo inferior de la cabeza e inerva la piel de la nuca y del cuero cabelludo.",
 ["Recoge la sensibilidad de la piel retroauricular.", "Recoge la sensibilidad de la nuca y el cuero cabelludo; no inerva los suboccipitales.", "Inerva el trapecio y el ECM.", "Inerva la piel de la parte baja de la nuca.", ""]],
},
"mu-141ea87a": {
"en": ["Which muscle turns the head to the same side and forms the inferior border of the suboccipital triangle?",
 ["Rectus capitis posterior minor", "Longus capitis", "Obliquus capitis inferior", "Rectus capitis lateralis", "Obliquus capitis superior"],
 "Obliquus capitis inferior, running from the spine of the axis to the transverse process of the atlas, is the only suboccipital muscle that does not attach to the skull; it rotates the atlas and head on the axis to the same side.", []],
"fr": ["Quel muscle tourne la tête du même côté et forme le bord inférieur du triangle sous-occipital ?",
 ["Petit droit postérieur de la tête", "Long de la tête", "Oblique inférieur de la tête", "Droit latéral de la tête", "Oblique supérieur de la tête"],
 "L'oblique inférieur de la tête, tendu du processus épineux de l'axis au processus transverse de l'atlas, est le seul muscle sous-occipital qui ne s'insère pas sur le crâne ; il fait tourner l'atlas et la tête sur l'axis du même côté.", []],
"de": ["Welcher Muskel dreht den Kopf zur gleichen Seite und bildet die untere Grenze des Trigonum suboccipitale?",
 ["M. rectus capitis posterior minor", "M. longus capitis", "M. obliquus capitis inferior", "M. rectus capitis lateralis", "M. obliquus capitis superior"],
 "Der vom Dornfortsatz des Axis zum Querfortsatz des Atlas ziehende Obliquus capitis inferior ist der einzige subokzipitale Muskel ohne Ansatz am Schädel; er dreht Atlas und Kopf auf dem Axis zur gleichen Seite.", []],
"es": ["¿Qué músculo gira la cabeza hacia el mismo lado y forma el borde inferior del triángulo suboccipital?",
 ["Recto posterior menor de la cabeza", "Largo de la cabeza", "Oblicuo inferior de la cabeza", "Recto lateral de la cabeza", "Oblicuo superior de la cabeza"],
 "El oblicuo inferior de la cabeza, que va de la apófisis espinosa del axis a la apófisis transversa del atlas, es el único suboccipital que no se inserta en el cráneo; rota el atlas y la cabeza sobre el axis hacia el mismo lado.", []],
},
"mu-ff99c4dc": {
"en": ["Which structures bound the triangle of auscultation?",
 ["Trapezius, latissimus dorsi and the medial border of the scapula", "Trapezius, sternocleidomastoid and clavicle", "Latissimus dorsi, external oblique and iliac crest", "Quadratus lumborum, 12th rib and internal oblique", "Teres major, teres minor and the long head of triceps"],
 "In the triangle of auscultation the muscle layer is thin; when the patient leans forwards and folds the arms, the scapula moves laterally, the triangle widens and lung sounds are heard better. The other options are the inferior lumbar (Petit), superior lumbar (Grynfeltt), posterior cervical triangles and the scapular spaces.", []],
"fr": ["Quelles structures limitent le triangle d'auscultation ?",
 ["Trapèze, grand dorsal et bord médial de la scapula", "Trapèze, sterno-cléido-mastoïdien et clavicule", "Grand dorsal, oblique externe et crête iliaque", "Carré des lombes, 12e côte et oblique interne", "Grand rond, petit rond et chef long du triceps"],
 "Dans le triangle d'auscultation, la couche musculaire est mince ; quand le patient se penche en avant et croise les bras, la scapula se déplace en dehors, le triangle s'élargit et les bruits pulmonaires sont mieux perçus. Les autres propositions correspondent aux trigones lombal inférieur (Petit), lombal supérieur (Grynfeltt), au trigone cervical postérieur et aux espaces scapulaires.", []],
"de": ["Welche Strukturen begrenzen das Auskultationsdreieck (Trigonum auscultationis)?",
 ["M. trapezius, M. latissimus dorsi und medialer Schulterblattrand", "M. trapezius, M. sternocleidomastoideus und Clavicula", "M. latissimus dorsi, M. obliquus externus abdominis und Crista iliaca", "M. quadratus lumborum, 12. Rippe und M. obliquus internus", "M. teres major, M. teres minor und Caput longum des M. triceps"],
 "Im Auskultationsdreieck ist die Muskelschicht dünn; beugt sich der Patient vor und verschränkt die Arme, gleitet das Schulterblatt nach lateral, das Dreieck wird größer und Lungengeräusche sind besser hörbar. Die anderen Optionen sind unteres (Petit) und oberes (Grynfeltt) Lumbaldreieck, seitliches Halsdreieck und Achsellücken.", []],
"es": ["¿Qué estructuras limitan el triángulo de auscultación?",
 ["Trapecio, dorsal ancho y borde medial de la escápula", "Trapecio, esternocleidomastoideo y clavícula", "Dorsal ancho, oblicuo externo y cresta ilíaca", "Cuadrado lumbar, 12.ª costilla y oblicuo interno", "Redondo mayor, redondo menor y cabeza larga del tríceps"],
 "En el triángulo de auscultación la capa muscular es fina; cuando el paciente se inclina hacia delante y cruza los brazos, la escápula se desplaza lateralmente, el triángulo se ensancha y los ruidos pulmonares se oyen mejor. Las demás opciones corresponden a los triángulos lumbar inferior (Petit), lumbar superior (Grynfeltt), cervical posterior y a los espacios escapulares.", []],
},
"mu-d850fa84": {
"en": ["Which is the most lateral column of erector spinae?",
 ["Longissimus", "Multifidus", "Semispinalis", "Iliocostalis", "Spinalis"],
 "From lateral to medial erector spinae consists of the iliocostalis, longissimus and spinalis columns ('I Love Spaghetti'). Multifidus and semispinalis belong to the deeper transversospinal group. All are supplied by the posterior rami of the spinal nerves.", []],
"fr": ["Quelle est la colonne la plus latérale de l'érecteur du rachis ?",
 ["Longissimus", "Multifide", "Semi-épineux", "Ilio-costal", "Épineux"],
 "De dehors en dedans, l'érecteur du rachis comprend les colonnes ilio-costale, longissimus et épineuse. Le multifide et le semi-épineux appartiennent au groupe transversaire épineux, plus profond. Tous sont innervés par les rameaux postérieurs des nerfs spinaux.", []],
"de": ["Welche Säule des M. erector spinae liegt am weitesten lateral?",
 ["M. longissimus", "M. multifidus", "M. semispinalis", "M. iliocostalis", "M. spinalis"],
 "Der Erector spinae besteht von lateral nach medial aus Iliocostalis, Longissimus und Spinalis. Multifidus und Semispinalis gehören zur tieferen transversospinalen Gruppe. Alle werden von den Rr. posteriores der Spinalnerven innerviert.", []],
"es": ["¿Cuál es la columna más lateral del erector de la columna?",
 ["Longísimo", "Multífido", "Semiespinoso", "Iliocostal", "Espinoso"],
 "De lateral a medial el erector de la columna está formado por las columnas iliocostal, longísimo y espinoso. El multífido y el semiespinoso pertenecen al grupo transversoespinoso, más profundo. Todos los inervan los ramos posteriores de los nervios espinales.", []],
},
"mu-f74bf272": {
"en": ["Which transversospinal muscle is thickest in the lumbar region and plays an important role in segmental stabilisation?",
 ["Multifidus", "Rotatores", "Spinalis", "Iliocostalis", "Semispinalis"],
 "Multifidus extends from the sacrum to C2 and is thickest in the lumbar region; it binds each vertebra to the 2–4 below and stabilises the segments. Its wasting and fatty infiltration are common in chronic low back pain. Semispinalis is prominent in the thoracic–cervical region, rotatores in the thoracic region.", []],
"fr": ["Quel muscle transversaire épineux est le plus épais dans la région lombale et joue un rôle important dans la stabilisation segmentaire ?",
 ["Multifide", "Rotateurs", "Épineux", "Ilio-costal", "Semi-épineux"],
 "Le multifide s'étend du sacrum à C2 et est le plus épais dans la région lombale ; il relie chaque vertèbre aux 2 à 4 vertèbres sous-jacentes et stabilise les segments. Son amyotrophie et son infiltration graisseuse sont fréquentes dans la lombalgie chronique. Le semi-épineux prédomine aux régions thoracique et cervicale, les rotateurs à la région thoracique.", []],
"de": ["Welcher transversospinale Muskel ist im Lendenbereich am kräftigsten und wichtig für die segmentale Stabilisierung?",
 ["M. multifidus", "Mm. rotatores", "M. spinalis", "M. iliocostalis", "M. semispinalis"],
 "Der Multifidus reicht vom Kreuzbein bis C2 und ist lumbal am kräftigsten; er verbindet jeden Wirbel mit den 2–4 darunterliegenden und stabilisiert die Segmente. Bei chronischen Rückenschmerzen sind Atrophie und Verfettung häufig. Der Semispinalis ist thorakozervikal, die Rotatores sind thorakal ausgeprägt.", []],
"es": ["¿Qué músculo transversoespinoso es el más grueso en la región lumbar y tiene un papel importante en la estabilización segmentaria?",
 ["Multífido", "Rotadores", "Espinoso", "Iliocostal", "Semiespinoso"],
 "El multífido va del sacro a C2 y es más grueso en la región lumbar; une cada vértebra a las 2–4 inferiores y estabiliza los segmentos. Su atrofia e infiltración grasa son frecuentes en el dolor lumbar crónico. El semiespinoso predomina en la región toracocervical y los rotadores en la torácica.", []],
},
"mu-9657aa4e": {
"en": ["Where does rhomboid major insert?",
 ["Medial border of the scapula, from the root of the spine to the inferior angle", "Coracoid process", "The small part of the medial border of the scapula at the level of the spine", "Superior angle of the scapula", "Along the medial border of the anterior surface of the scapula"],
 "Rhomboid major arises from the spinous processes of T2–T5 and inserts into the part of the medial border of the scapula below the spine; rhomboid minor runs from C7–T1 to the level of the root of the spine. Both are supplied by the dorsal scapular nerve and pull the scapula backwards and upwards.",
 ["", "This is the insertion of pectoralis minor.", "This is the insertion of rhomboid minor.", "This is the insertion of levator scapulae.", "This is the insertion of serratus anterior."]],
"fr": ["Où s'insère le grand rhomboïde ?",
 ["Sur le bord médial de la scapula, de la racine de l'épine à l'angle inférieur", "Sur le processus coracoïde", "Sur la petite portion du bord médial en regard de l'épine", "Sur l'angle supérieur de la scapula", "Le long du bord médial de la face antérieure de la scapula"],
 "Le grand rhomboïde naît des processus épineux de T2 à T5 et s'insère sur la partie du bord médial de la scapula située sous l'épine ; le petit rhomboïde va de C7–T1 au niveau de la racine de l'épine. Tous deux sont innervés par le nerf dorsal de la scapula et attirent la scapula en arrière et en haut.",
 ["", "C'est l'insertion du petit pectoral.", "C'est l'insertion du petit rhomboïde.", "C'est l'insertion de l'élévateur de la scapula.", "C'est l'insertion du dentelé antérieur."]],
"de": ["Wo setzt der M. rhomboideus major an?",
 ["Am Margo medialis scapulae von der Spinawurzel bis zum Angulus inferior", "Am Processus coracoideus", "Am kleinen Abschnitt des medialen Randes auf Höhe der Spina", "Am Angulus superior scapulae", "Entlang des medialen Randes der Schulterblattvorderfläche"],
 "Der Rhomboideus major entspringt an den Dornfortsätzen T2–T5 und setzt am medialen Schulterblattrand unterhalb der Spina an; der Rhomboideus minor zieht von C7–T1 zur Höhe der Spinawurzel. Beide werden vom N. dorsalis scapulae innerviert und ziehen das Schulterblatt nach hinten oben.",
 ["", "Das ist der Ansatz des Pectoralis minor.", "Das ist der Ansatz des Rhomboideus minor.", "Das ist der Ansatz des Levator scapulae.", "Das ist der Ansatz des Serratus anterior."]],
"es": ["¿Dónde se inserta el romboides mayor?",
 ["En el borde medial de la escápula, desde la raíz de la espina hasta el ángulo inferior", "En la apófisis coracoides", "En la pequeña porción del borde medial a la altura de la espina", "En el ángulo superior de la escápula", "A lo largo del borde medial de la cara anterior de la escápula"],
 "El romboides mayor nace de las apófisis espinosas de T2–T5 y se inserta en la parte del borde medial de la escápula situada bajo la espina; el menor va de C7–T1 a la altura de la raíz de la espina. Ambos los inerva el nervio dorsal de la escápula y llevan la escápula hacia atrás y arriba.",
 ["", "Es la inserción del pectoral menor.", "Es la inserción del romboides menor.", "Es la inserción del elevador de la escápula.", "Es la inserción del serrato anterior."]],
},
"mu-7e7967a0": {
"en": ["Where does levator scapulae arise?",
 ["Posterior tubercles of the transverse processes of C1–C4", "Anterior tubercles of the transverse processes of C3–C6", "Superior nuchal line and nuchal ligament", "Spinous processes of C7–T5", "Upper surface of the 1st rib"],
 "Levator scapulae arises from the upper cervical vertebrae and attaches to the superior angle and upper medial border of the scapula. It elevates the scapula and rotates it downwards; it is supplied by the dorsal scapular nerve and branches of C3–C4.", []],
"fr": ["D'où naît l'élévateur de la scapula ?",
 ["Des tubercules postérieurs des processus transverses de C1–C4", "Des tubercules antérieurs des processus transverses de C3–C6", "De la ligne nucale supérieure et du ligament nucal", "Des processus épineux de C7–T5", "De la face supérieure de la 1re côte"],
 "L'élévateur de la scapula naît des vertèbres cervicales hautes et s'insère sur l'angle supérieur et la partie haute du bord médial de la scapula. Il élève la scapula et la fait tourner vers le bas ; il est innervé par le nerf dorsal de la scapula et des branches de C3–C4.", []],
"de": ["Wo entspringt der M. levator scapulae?",
 ["An den Tubercula posteriora der Querfortsätze C1–C4", "An den Tubercula anteriora der Querfortsätze C3–C6", "An Linea nuchae superior und Lig. nuchae", "An den Dornfortsätzen C7–T5", "An der Oberfläche der 1. Rippe"],
 "Der Levator scapulae entspringt an den oberen Halswirbeln und setzt am Angulus superior und am oberen Teil des medialen Schulterblattrandes an. Er hebt das Schulterblatt und dreht es nach unten; innerviert wird er vom N. dorsalis scapulae und Ästen aus C3–C4.", []],
"es": ["¿Dónde nace el elevador de la escápula?",
 ["En los tubérculos posteriores de las apófisis transversas de C1–C4", "En los tubérculos anteriores de las apófisis transversas de C3–C6", "En la línea nucal superior y el ligamento nucal", "En las apófisis espinosas de C7–T5", "En la cara superior de la 1.ª costilla"],
 "El elevador de la escápula nace de las vértebras cervicales altas y se inserta en el ángulo superior y la parte alta del borde medial de la escápula. Eleva la escápula y la rota hacia abajo; lo inervan el nervio dorsal de la escápula y ramas de C3–C4.", []],
},
"mu-5b14c6af": {
"en": ["Which of the following is NOT an action of latissimus dorsi?",
 ["External rotation of the arm", "Adduction of the arm", "Pulling the trunk up with the arms fixed", "Extension of the arm", "Internal rotation of the arm"],
 "Latissimus dorsi attaches to the floor of the intertubercular sulcus; it extends, adducts and internally rotates the arm (the 'swimmer's muscle'). With the arms fixed (pull-up) it pulls the trunk upwards. External rotation is the job of infraspinatus and teres minor.", []],
"fr": ["Lequel de ces mouvements N'EST PAS une action du grand dorsal ?",
 ["Rotation latérale du bras", "Adduction du bras", "Élévation du tronc bras fixés", "Extension du bras", "Rotation médiale du bras"],
 "Le grand dorsal s'insère au fond du sillon intertuberculaire ; il porte le bras en extension, adduction et rotation médiale (« muscle du nageur »). Bras fixés (traction à la barre), il élève le tronc. La rotation latérale est assurée par l'infra-épineux et le petit rond.", []],
"de": ["Welche der folgenden Bewegungen ist KEINE Funktion des M. latissimus dorsi?",
 ["Außenrotation des Arms", "Adduktion des Arms", "Hochziehen des Rumpfes bei fixierten Armen", "Extension des Arms", "Innenrotation des Arms"],
 "Der Latissimus dorsi setzt am Boden des Sulcus intertubercularis an; er streckt, adduziert und innenrotiert den Arm („Schwimmermuskel“). Bei fixierten Armen (Klimmzug) zieht er den Rumpf hoch. Die Außenrotation ist Aufgabe von Infraspinatus und Teres minor.", []],
"es": ["¿Cuál de los siguientes NO es una acción del dorsal ancho?",
 ["Rotación externa del brazo", "Aducción del brazo", "Elevar el tronco con los brazos fijos", "Extensión del brazo", "Rotación interna del brazo"],
 "El dorsal ancho se inserta en el fondo del surco intertubercular; extiende, aduce y rota internamente el brazo («músculo del nadador»). Con los brazos fijos (dominada) eleva el tronco. La rotación externa corresponde al infraespinoso y al redondo menor.", []],
},
}
